package com.flowdesk.alert.recovery;

import com.flowdesk.alert.event.AlertEventContract;import com.flowdesk.alert.repository.AlertRepository;import org.springframework.jdbc.core.JdbcTemplate;import java.sql.ResultSet;import java.sql.SQLException;import java.sql.Timestamp;import java.time.Instant;import java.util.ArrayList;import java.util.HexFormat;import java.util.List;import java.util.Optional;import java.util.UUID;
final class AlertRecoveryRepository{private final JdbcTemplate jdbc;AlertRecoveryRepository(JdbcTemplate j){jdbc=j;}
    Optional<Recovery> find(UUID tenant,UUID id,boolean lock){return jdbc.query("""
            SELECT recovery_id,direction,source_record_id,business_intent_key,state,attempt_count,next_attempt_at,last_error_code,last_error_summary,dead_lettered_at,recovery_required_at,replay_count,last_replayed_at,last_replayed_by_type,last_replayed_by_id,last_replay_reason,last_replay_correlation_id,resolved_at,lock_version,created_at,updated_at FROM message_recovery WHERE tenant_id=? AND recovery_id=?
            """+(lock?" FOR UPDATE":""),MAPPER,AlertRepository.bytes(tenant),AlertRepository.bytes(id)).stream().findFirst();}
    List<Recovery> list(UUID tenant,String direction,String state,Boolean dead,String error,Instant from,Instant to,boolean asc,boolean deadSort,Instant cursor,UUID cursorId,int limit){String column=deadSort?"dead_lettered_at":"recovery_required_at";StringBuilder sql=new StringBuilder("""
            SELECT recovery_id,direction,source_record_id,business_intent_key,state,attempt_count,next_attempt_at,last_error_code,last_error_summary,dead_lettered_at,recovery_required_at,replay_count,last_replayed_at,last_replayed_by_type,last_replayed_by_id,last_replay_reason,last_replay_correlation_id,resolved_at,lock_version,created_at,updated_at FROM message_recovery WHERE tenant_id=?
            """);List<Object>a=new ArrayList<>();a.add(AlertRepository.bytes(tenant));if(direction!=null){sql.append(" AND direction=?");a.add(direction);}if(state!=null){sql.append(" AND state=?");a.add(state);}if(dead!=null)sql.append(dead?" AND dead_lettered_at IS NOT NULL":" AND dead_lettered_at IS NULL");if(error!=null){sql.append(" AND last_error_code=?");a.add(error);}if(from!=null){sql.append(" AND recovery_required_at>=?");a.add(Timestamp.from(from));}if(to!=null){sql.append(" AND recovery_required_at<=?");a.add(Timestamp.from(to));}if(deadSort)sql.append(" AND dead_lettered_at IS NOT NULL");if(cursor!=null){String cmp=asc?">":"<";sql.append(" AND (").append(column).append(' ').append(cmp).append(" ? OR (").append(column).append("=? AND recovery_id ").append(cmp).append(" ?))");a.add(Timestamp.from(cursor));a.add(Timestamp.from(cursor));a.add(AlertRepository.bytes(cursorId));}sql.append(" ORDER BY ").append(column).append(asc?" ASC":" DESC").append(",recovery_id").append(asc?" ASC":" DESC").append(" LIMIT ").append(limit);return jdbc.query(sql.toString(),MAPPER,a.toArray());}
    Optional<Inbox> inbox(UUID tenant,UUID id,boolean lock){return jdbc.query("""
            SELECT inbox_id,message_id,business_intent_key,contract_ref,contract_version,body_bytes,body_sha256,correlation_id,causation_id,occurred_at,status,lock_version FROM inbox_message WHERE tenant_id=? AND inbox_id=?
            """+(lock?" FOR UPDATE":""),(rs,n)->new Inbox(AlertRepository.uuid(rs.getBytes(1)),AlertRepository.uuid(rs.getBytes(2)),rs.getBytes(3),rs.getString(4),rs.getInt(5),rs.getBytes(6),rs.getBytes(7),AlertRepository.uuid(rs.getBytes(8)),AlertRepository.uuid(rs.getBytes(9)),instant(rs,"occurred_at"),rs.getString(11),rs.getLong(12)),AlertRepository.bytes(tenant),AlertRepository.bytes(id)).stream().findFirst();}
    Optional<Outbox> outbox(UUID tenant,UUID id,boolean lock){return jdbc.query("""
            SELECT o.outbox_id,o.contract_ref,o.contract_version,o.aggregate_id,o.correlation_id,o.status,o.lock_version,l.status AS link_status,l.lock_version AS link_version FROM outbox_event o LEFT JOIN incident_ticket_link l ON l.tenant_id=o.tenant_id AND l.incident_id=o.aggregate_id WHERE o.tenant_id=? AND o.outbox_id=?
            """+(lock?" FOR UPDATE":""),(rs,n)->new Outbox(AlertRepository.uuid(rs.getBytes(1)),rs.getString(2),rs.getInt(3),AlertRepository.uuid(rs.getBytes(4)),AlertRepository.uuid(rs.getBytes(5)),rs.getString(6),rs.getLong(7),rs.getString(8),rs.getLong(9)),AlertRepository.bytes(tenant),AlertRepository.bytes(id)).stream().findFirst();}
    int acceptInbox(UUID tenant,Recovery r,UUID actor,String reason,UUID corr,Instant now){return mark(tenant,r,actor,reason,corr,now);}
    int acceptOutbox(UUID tenant,Recovery r,Outbox source,UUID actor,String reason,UUID corr,Instant now){int n=mark(tenant,r,actor,reason,corr,now);if(n!=1)return n;int out=jdbc.update("""
            UPDATE outbox_event SET status='PENDING',attempt_count=0,next_attempt_at=?,locked_by=NULL,locked_at=NULL,last_error_code=NULL,broker_confirmed_at=NULL,lock_version=lock_version+1,updated_at=?,updated_by_type='SERVICE' WHERE tenant_id=? AND outbox_id=? AND status='RECOVERY_REQUIRED' AND lock_version=?
            """,Timestamp.from(now),Timestamp.from(now),AlertRepository.bytes(tenant),AlertRepository.bytes(source.outboxId()),source.version());if(out!=1)throw new IllegalStateException("Alert Outbox replay CAS lost");if(AlertEventContract.TICKET_CREATE_REQUESTED.contractRef().equals(source.contractRef())){int link=jdbc.update("""
            UPDATE incident_ticket_link SET status='REQUESTED',recovery_required_at=NULL,recovery_reason_code=NULL,lock_version=lock_version+1,updated_at=?,updated_by_type='SERVICE' WHERE tenant_id=? AND incident_id=? AND status='RECOVERY_REQUIRED' AND lock_version=?
            """,Timestamp.from(now),AlertRepository.bytes(tenant),AlertRepository.bytes(source.incidentId()),source.linkVersion());if(link!=1)throw new IllegalStateException("IncidentTicketLink replay CAS lost");}return 1;}
    private int mark(UUID tenant,Recovery r,UUID actor,String reason,UUID corr,Instant now){return jdbc.update("""
            UPDATE message_recovery SET state='REPLAYING',next_attempt_at=NULL,replay_count=replay_count+1,last_replayed_at=?,last_replayed_by_type='USER',last_replayed_by_id=?,last_replay_reason=?,last_replay_correlation_id=?,lock_version=lock_version+1,updated_at=?,updated_by_type='USER',updated_by_id=? WHERE tenant_id=? AND recovery_id=? AND direction=? AND source_record_id=? AND state='OPEN' AND lock_version=?
            """,Timestamp.from(now),AlertRepository.bytes(actor),reason,AlertRepository.bytes(corr),Timestamp.from(now),AlertRepository.bytes(actor),AlertRepository.bytes(tenant),AlertRepository.bytes(r.id()),r.direction(),AlertRepository.bytes(r.source()),r.version());}
    int reopen(UUID tenant,UUID id,UUID corr,String error,Instant now){return jdbc.update("""
            UPDATE message_recovery SET state='OPEN',last_error_code=?,last_error_summary='Controlled same-path replay did not reach a local terminal result.',lock_version=lock_version+1,updated_at=?,updated_by_type='SERVICE' WHERE tenant_id=? AND recovery_id=? AND state='REPLAYING' AND last_replay_correlation_id=?
            """,error,Timestamp.from(now),AlertRepository.bytes(tenant),AlertRepository.bytes(id),AlertRepository.bytes(corr));}
    Optional<Audit> audit(UUID tenant,UUID id){return jdbc.query("SELECT action_code,target_id,outcome,actor_type,actor_id,reason,error_code,correlation_id,causation_id FROM audit_record WHERE tenant_id=? AND audit_id=?",(rs,n)->new Audit(rs.getString(1),AlertRepository.uuid(rs.getBytes(2)),rs.getString(3),rs.getString(4),AlertRepository.uuid(rs.getBytes(5)),rs.getString(6),rs.getString(7),AlertRepository.uuid(rs.getBytes(8)),AlertRepository.uuid(rs.getBytes(9))),AlertRepository.bytes(tenant),AlertRepository.bytes(id)).stream().findFirst();}
    void audit(UUID tenant,UUID id,String action,UUID recovery,String outcome,UUID actor,String reason,String error,UUID corr,UUID cause,Instant now){jdbc.update("""
            INSERT INTO audit_record(tenant_id,audit_id,action_code,target_type,target_id,outcome,actor_type,actor_id,reason,error_code,correlation_id,causation_id,occurred_at,recorded_at) VALUES(?,?,?,'MESSAGE_RECOVERY',?,?,'USER',?,?,?,?,?,?,?)
            """,AlertRepository.bytes(tenant),AlertRepository.bytes(id),action,AlertRepository.bytes(recovery),outcome,AlertRepository.bytes(actor),reason,error,AlertRepository.bytes(corr),AlertRepository.bytes(cause),Timestamp.from(now),Timestamp.from(now));}
    static AlertRecoveryView view(Recovery f){return new AlertRecoveryView(f.id(),"ALERT",f.direction(),f.source(),HexFormat.of().formatHex(f.intent()),f.state(),f.attempts(),f.next(),f.error(),f.summary(),f.dead(),f.required(),f.replays(),f.replayedAt(),f.replayedBy()==null?null:new AlertRecoveryView.ReplayedBy(f.replayedType(),f.replayedBy()),f.reason(),f.resolved(),f.version(),f.created(),f.updated());}
    private static Instant instant(ResultSet rs,String f)throws SQLException{Timestamp t=rs.getTimestamp(f);return t==null?null:t.toInstant();}private static final org.springframework.jdbc.core.RowMapper<Recovery>MAPPER=(rs,n)->new Recovery(AlertRepository.uuid(rs.getBytes("recovery_id")),rs.getString("direction"),AlertRepository.uuid(rs.getBytes("source_record_id")),rs.getBytes("business_intent_key"),rs.getString("state"),rs.getInt("attempt_count"),instant(rs,"next_attempt_at"),rs.getString("last_error_code"),rs.getString("last_error_summary"),instant(rs,"dead_lettered_at"),instant(rs,"recovery_required_at"),rs.getInt("replay_count"),instant(rs,"last_replayed_at"),rs.getString("last_replayed_by_type"),AlertRepository.uuid(rs.getBytes("last_replayed_by_id")),rs.getString("last_replay_reason"),AlertRepository.uuid(rs.getBytes("last_replay_correlation_id")),instant(rs,"resolved_at"),rs.getLong("lock_version"),instant(rs,"created_at"),instant(rs,"updated_at"));
    record Recovery(UUID id,String direction,UUID source,byte[] intent,String state,int attempts,Instant next,String error,String summary,Instant dead,Instant required,int replays,Instant replayedAt,String replayedType,UUID replayedBy,String reason,UUID replayCorrelation,Instant resolved,long version,Instant created,Instant updated){}record Inbox(UUID inboxId,UUID messageId,byte[] intent,String contractRef,int contractVersion,byte[] body,byte[] hash,UUID correlation,UUID causation,Instant occurred,String status,long version){}record Outbox(UUID outboxId,String contractRef,int contractVersion,UUID incidentId,UUID correlation,String status,long version,String linkStatus,long linkVersion){}record Audit(String action,UUID target,String outcome,String actorType,UUID actor,String reason,String error,UUID correlation,UUID causation){}
}
